fn char_keysym(c: char, location: KeyLocation) -> String {
  if location == KeyLocation::Numpad {
    let kp = match c {
      '0'..='9' => return format!("KP_{c}"),
      '+' => Some("KP_Add"),
      '-' => Some("KP_Subtract"),
      '*' => Some("KP_Multiply"),
      '/' => Some("KP_Divide"),
      '.' => Some("KP_Decimal"),
      ',' => Some("KP_Separator"),
      '=' => Some("KP_Equal"),
      ' ' => Some("KP_Space"),
      '\t' => Some("KP_Tab"),
      '\r' | '\n' => Some("KP_Enter"),
      _ => None,
    };
    if let Some(kp) = kp {
      return kp.to_string();
    }
  }

  let name = match c {
    ' ' => "space",
    '!' => "exclam",
    '"' => "quotedbl",
    '#' => "numbersign",
    '$' => "dollar",
    '%' => "percent",
    '&' => "ampersand",
    '\'' => "apostrophe",
    '(' => "parenleft",
    ')' => "parenright",
    '*' => "asterisk",
    '+' => "plus",
    ',' => "comma",
    '-' => "minus",
    '.' => "period",
    '/' => "slash",
    ':' => "colon",
    ';' => "semicolon",
    '<' => "less",
    '=' => "equal",
    '>' => "greater",
    '?' => "question",
    '@' => "at",
    '[' => "bracketleft",
    '\\' => "backslash",
    ']' => "bracketright",
    '^' => "asciicircum",
    '_' => "underscore",
    '`' => "grave",
    '{' => "braceleft",
    '|' => "bar",
    '}' => "braceright",
    '~' => "asciitilde",
    '\t' => "Tab",
    '\r' | '\n' => "Return",
    '\u{8}' => "BackSpace",
    '\u{1b}' => "Escape",
    '\u{7f}' => "Delete",
    '\u{a0}'..='\u{ff}' => LATIN1[c as usize - 0xa0],
    _ => return c.to_string(),
  };
  name.to_string()
}

