#[cfg(test)]
mod tests {
  use super::*;

  fn detail(key: Key) -> String {
    key_detail(&key, KeyLocation::Standard)
  }

  #[test]
  fn named_keys_map_to_tk_keysyms() {
    assert_eq!(detail(Key::Character("a".into())), "a");
    assert_eq!(detail(Key::Named(NamedKey::ArrowUp)), "Up");
    assert_eq!(detail(Key::Named(NamedKey::Enter)), "Return");
    assert_eq!(detail(Key::Named(NamedKey::Space)), "space");
    assert_eq!(detail(Key::Named(NamedKey::Backspace)), "BackSpace");
    assert_eq!(detail(Key::Named(NamedKey::PageUp)), "Prior");
    assert_eq!(detail(Key::Named(NamedKey::PageDown)), "Next");
    assert_eq!(detail(Key::Named(NamedKey::CapsLock)), "Caps_Lock");
    assert_eq!(detail(Key::Named(NamedKey::F12)), "F12");
    assert_eq!(detail(Key::Named(NamedKey::F35)), "F35");
    assert_eq!(
      detail(Key::Named(NamedKey::AudioVolumeUp)),
      "XF86AudioRaiseVolume"
    );
  }

  #[test]
  fn characters_map_to_keysym_names() {
    assert_eq!(detail(Key::Character("A".into())), "A");
    assert_eq!(detail(Key::Character("7".into())), "7");
    assert_eq!(detail(Key::Character(" ".into())), "space");
    assert_eq!(detail(Key::Character("!".into())), "exclam");
    assert_eq!(detail(Key::Character("@".into())), "at");
    assert_eq!(detail(Key::Character("[".into())), "bracketleft");
    assert_eq!(detail(Key::Character("~".into())), "asciitilde");
    assert_eq!(detail(Key::Character("é".into())), "eacute");
    assert_eq!(detail(Key::Character("ß".into())), "ssharp");
    assert_eq!(detail(Key::Character("λ".into())), "λ");
  }

  #[test]
  fn modifiers_distinguish_left_and_right() {
    let shift = Key::Named(NamedKey::Shift);
    assert_eq!(key_detail(&shift, KeyLocation::Left), "Shift_L");
    assert_eq!(key_detail(&shift, KeyLocation::Right), "Shift_R");
    let ctrl = Key::Named(NamedKey::Control);
    assert_eq!(key_detail(&ctrl, KeyLocation::Left), "Control_L");
    assert_eq!(key_detail(&ctrl, KeyLocation::Right), "Control_R");
    let alt = Key::Named(NamedKey::Alt);
    assert_eq!(key_detail(&alt, KeyLocation::Right), "Alt_R");
    let sup = Key::Named(NamedKey::Super);
    assert_eq!(key_detail(&sup, KeyLocation::Left), "Super_L");
  }

  #[test]
  fn numpad_keys_use_kp_names() {
    let kp = |key: Key| key_detail(&key, KeyLocation::Numpad);
    assert_eq!(kp(Key::Named(NamedKey::Enter)), "KP_Enter");
    assert_eq!(kp(Key::Named(NamedKey::ArrowUp)), "KP_Up");
    assert_eq!(kp(Key::Named(NamedKey::PageDown)), "KP_Next");
    assert_eq!(kp(Key::Named(NamedKey::NumLock)), "Num_Lock");
    assert_eq!(kp(Key::Character("0".into())), "KP_0");
    assert_eq!(kp(Key::Character("9".into())), "KP_9");
    assert_eq!(kp(Key::Character("+".into())), "KP_Add");
    assert_eq!(kp(Key::Character(".".into())), "KP_Decimal");
  }
}
